import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseDuration } from '../duration.js';
test('valid', () => {
  assert.equal(parseDuration('1h30m'), 5400);
  assert.equal(parseDuration('2d 4h'), 187200);
  assert.equal(parseDuration('45s'), 45);
  assert.equal(parseDuration('1.5h'), 5400);
  assert.equal(parseDuration('1d 1h 1m 1s'), 90061);
});
test('invalid', () => { for (const s of ['', '10', '1m1h', '1h1h', 'h', '1x', '1h 30']) assert.throws(() => parseDuration(s), Error, s); });

