export function parseDuration(text) {
  const m = /^\s*(?:(\d+(?:\.\d+)?)d)?\s*(?:(\d+(?:\.\d+)?)h)?\s*(?:(\d+(?:\.\d+)?)m)?\s*(?:(\d+(?:\.\d+)?)s)?\s*$/.exec(text);
  if (!m || m.slice(1).every((x) => x === undefined)) throw new Error('bad duration: ' + text);
  const [d, h, mi, s] = m.slice(1).map((x) => Number(x ?? 0));
  return d * 86400 + h * 3600 + mi * 60 + s;
}
